// Hidden: it emits a live credential, so it's a deliberate scripting escape
// hatch, not part of the everyday surface. It resolves the same bearer the API
// client would — ENTIRE_TOKEN verbatim when set, otherwise the active context's
// login JWT, refreshed if it's near expiry — and prints nothing but the token
// (errors and the not-logged-in hint go to stderr) so command substitution
// stays clean.
//
// With --jurisdiction/-j it instead exchanges that same login credential for a
// jurisdictional identity token (scope=openid) audienced to the given
// jurisdiction in the ACTIVE CONTEXT'S environment — so a partial.to login mints
// a partial.to jurisdiction token, not a hardwired entire.io one. This is the
// credential a repo-hosting entire-api cell accepts (the control-plane bearer
// and the BFF api-access token are not accepted there).
func newAuthTokenCmd() *cobra.Command {
	var insecureHTTPAuth bool
	var jurisdiction string
	cmd := &cobra.Command{
		Use:    "token",
		Short:  "Print the active control-plane bearer token (for scripting)",
		Hidden: true,
		Args:   cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			// Refresh may exchange/refresh over the network; honor the
			// plain-HTTP opt-in before resolving so local dev cores work.
			insecure := applyInsecureHTTPAuth(insecureHTTPAuth)
			target, err := resolveAuthStatusTarget(cmd.Context(), auth.Contexts, auth.RefreshedLoginToken)
			if err != nil {
				return err
			}
			// Don't mint/print a bearer for an insecure core unless explicitly
			// opted in — the token would otherwise be usable over plain HTTP.
			// Mirrors `auth status`.
			if !insecure && target.coreURL != "" {
				if err := api.RequireSecureURL(target.coreURL); err != nil {
					cmd.SilenceUsage = true
					return fmt.Errorf("login server URL check: %w", err)
				}
			}
			if target.token == "" {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not logged in. Run 'entire login' to authenticate.")
				return NewSilentError(errors.New("not logged in"))
			}
			// --jurisdiction: exchange the resolved login credential for a
			// jurisdictional identity token. The environment (prod vs staging) is
			// derived from target.coreURL — the active context's core (or the env
			// token's aud) — never a hardcoded entire.io base.
			if j := strings.TrimSpace(jurisdiction); j != "" {
				jtoken, _, _, mintErr := auth.MintJurisdictionIdentityToken(cmd.Context(), target.coreURL, target.token, j, insecure)
				if mintErr != nil {
					cmd.SilenceUsage = true
					return fmt.Errorf("mint jurisdictional token: %w", mintErr)
				}
				fmt.Fprintln(cmd.OutOrStdout(), jtoken)
				return nil
			}
			fmt.Fprintln(cmd.OutOrStdout(), target.token)
			return nil
		},
	}
	addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
	cmd.Flags().StringVarP(&jurisdiction, "jurisdiction", "j", "", "Mint a jurisdictional identity token for this jurisdiction slug (e.g. \"us\"), audienced to the active context's environment, instead of the control-plane bearer")
	return cmd
}

