	t.Setenv("ENTIRE_API_BASE_URL", "https://entire.io")
	if got := environmentFamily("https://entire.io", "https://us.auth.partial.to"); got != "entire.io" {
		t.Fatalf("family = %q, want entire.io (explicit override wins)", got)
