// TestMintJurisdictionIdentityToken exercises the exchange plumbing end-to-end
// against a loopback core (honoured verbatim), asserting the posted grant/scope/
// subject/audience and the returned token.
func TestMintJurisdictionIdentityToken(t *testing.T) {
	t.Setenv("ENTIRE_API_AUDIENCE_TEMPLATE", "https://{jurisdiction}.partial.to")
	t.Setenv("ENTIRE_CORE_BASE_URL_TEMPLATE", "")

	var gotAudience, gotSubject, gotScope, gotGrant string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != oauthTokenPath {
			http.NotFound(w, r)
			return
		}
		_ = r.ParseForm() //nolint:errcheck // test handler
		gotAudience = r.FormValue("audience")
		gotSubject = r.FormValue("subject_token")
		gotScope = r.FormValue("scope")
		gotGrant = r.FormValue("grant_type")
		w.Header().Set("Content-Type", "application/json")
		_, _ = fmt.Fprint(w, `{"access_token":"juris-token","token_type":"Bearer","expires_in":3600}`)
	}))
	defer srv.Close()
	t.Cleanup(SetCellExchangeTransportForTest(t, srv.Client().Transport))

	// srv.URL is loopback → jurisdictionCoreURL honours it verbatim, so the
	// exchange reaches the test server rather than a templated prod host.
	token, audience, core, err := MintJurisdictionIdentityToken(context.Background(), srv.URL, "login-jwt", "us", true)
	if err != nil {
		t.Fatalf("MintJurisdictionIdentityToken: %v", err)
	}
	if token != "juris-token" {
		t.Errorf("token = %q, want juris-token", token)
	}
	if audience != "https://us.partial.to" {
		t.Errorf("audience = %q, want https://us.partial.to", audience)
	}
	if core != srv.URL {
		t.Errorf("exchange core = %q, want %q", core, srv.URL)
	}
	if gotAudience != "https://us.partial.to" {
		t.Errorf("posted audience = %q, want https://us.partial.to", gotAudience)
	}
	if gotSubject != "login-jwt" {
		t.Errorf("posted subject_token = %q, want login-jwt", gotSubject)
	}
	if gotScope != jurisdictionIdentityScope {
		t.Errorf("posted scope = %q, want %q", gotScope, jurisdictionIdentityScope)
	}
	if gotGrant != httputil.GrantTypeTokenExchange {
		t.Errorf("posted grant_type = %q, want %q", gotGrant, httputil.GrantTypeTokenExchange)
	}
}

func TestMintJurisdictionIdentityTokenRejectsBadInput(t *testing.T) {
	t.Parallel()
	if _, _, _, err := MintJurisdictionIdentityToken(context.Background(), "https://us.auth.partial.to", "login-jwt", "", false); err == nil {
