	}
}

func TestJurisdictionCoreURLHonorsLoopbackAndFamily(t *testing.T) {

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/stretchr/testify/require"
)

// redirectTransport rewrites every request to point at target, so a mint that
// dials a templated prod host (https://us.auth.partial.to) is intercepted by a
// loopback httptest server. It records the last request it saw.
type redirectTransport struct {
	target *url.URL
}

func (rt redirectTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	clone := r.Clone(r.Context())
	clone.URL.Scheme = rt.target.Scheme
	clone.URL.Host = rt.target.Host
	clone.Host = rt.target.Host
	return http.DefaultTransport.RoundTrip(clone) //nolint:wrapcheck // test transport
}

