// environmentFamily picks the registrable apex to template jurisdiction URLs
// against, in precedence order:
//
//   - an EXPLICIT ENTIRE_API_BASE_URL override: the user deliberately pointed
//     the data plane at a specific environment, so its family wins. The *default*
//     data origin (prod entire.io, used when the env var is unset) must NOT win —
//     it would mask the login environment and mint an entire.io audience for a
//     partial.to session (the stored-context jurisdiction-mint bug this guards
//     against). ENTIRE_TOKEN callers pass the token's own core as dataOrigin, so
//     they are unaffected either way.
//   - otherwise the discovered login core: it is the core that issued / trusts
//     the login JWT being exchanged, so its environment is the one the minted
//     token must be audienced for. This lets a partial.to login yield a
//     partial.to audience even with the data-API origin left at its prod default.
//   - last resort (loopback/custom discovered core): the data origin's family.
func environmentFamily(dataOrigin, discoveredCore string) string {
	// Blank counts as unset, matching api.BaseURL()'s own TrimSpace check, so an
	// empty ENTIRE_API_BASE_URL doesn't masquerade as an explicit choice.
	if raw := strings.TrimSpace(os.Getenv(api.BaseURLEnvVar)); raw != "" {
		if fam := entireDomainFamily(dataOrigin); fam != "" {
			return fam
		}
	}
	if fam := entireDomainFamily(discoveredCore); fam != "" {
		return fam
	}
	return entireDomainFamily(dataOrigin)
}

