// TestEnvironmentFamilyPrefersDiscoveredCoreOverDefaultOrigin locks in the
// stored-context jurisdiction-mint fix: resolveStoredCellSubject sets dataOrigin
// to api.BaseURL(), which defaults to prod entire.io when ENTIRE_API_BASE_URL is
// unset. That default must NOT mask a staging (partial.to) discovered login
// core — otherwise a partial.to login mints an entire.io-audienced token. Only
// an EXPLICIT ENTIRE_API_BASE_URL override wins.
func TestEnvironmentFamilyPrefersDiscoveredCoreOverDefaultOrigin(t *testing.T) {
	const prodOrigin = "https://entire.io"
	// Empty ENTIRE_API_BASE_URL is treated as unset (matches api.BaseURL()).
	t.Setenv("ENTIRE_API_BASE_URL", "")
	if got := environmentFamily(prodOrigin, "https://us.auth.partial.to"); got != "partial.to" {
		t.Fatalf("family = %q, want partial.to (discovered core wins over default origin)", got)
	}
	if got := environmentFamily(prodOrigin, "https://us.auth.entire.io"); got != "entire.io" {
		t.Fatalf("family = %q, want entire.io", got)
	}
	// An explicit ENTIRE_API_BASE_URL override is a deliberate choice and wins,
	// even over a staging discovered core.
	t.Setenv("ENTIRE_API_BASE_URL", prodOrigin)
	if got := environmentFamily(prodOrigin, "https://us.auth.partial.to"); got != "entire.io" {
		t.Fatalf("family = %q, want entire.io (explicit override wins)", got)
	}
}

